package org.marketreview.nativeapp;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.content.ContentValues;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

final class PortfolioMirrorStore {
 private final File file;
 PortfolioMirrorStore(Context c,String name)throws Exception{PortfolioMirrorModel.need(name.matches("[A-Za-z0-9._-]+")&&!name.equals(".")&&!name.equals(".."),"需明确独立镜像数据库名");file=new File(c.getFilesDir(),name);try(SQLiteDatabase db=open()){}}
 File filePath(){return file;}
 private static void pragma(SQLiteDatabase db,String sql){try(Cursor q=db.rawQuery(sql,null)){q.moveToFirst();}}
 private SQLiteDatabase guardedOpen(int flags){
  if(file.exists())try(InputStream in=new FileInputStream(file)){
   byte[] header=new byte[16];int offset=0,n;while(offset<header.length&&(n=in.read(header,offset,header.length-offset))>0)offset+=n;
   if(offset!=16||!java.util.Arrays.equals(header,"SQLite format 3\000".getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw new android.database.sqlite.SQLiteDatabaseCorruptException("持仓镜像文件头无效；原文件保留");
  }catch(IOException error){throw new IllegalArgumentException("持仓镜像文件不可读取；原文件保留",error);}
  return SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,flags,corrupt->{throw new android.database.sqlite.SQLiteDatabaseCorruptException("持仓镜像数据库损坏；拒绝自动删除或修复原文件");});
 }
 private SQLiteDatabase open()throws Exception{boolean existed=file.exists();if(existed){try(SQLiteDatabase db=guardedOpen(SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS);Cursor q=db.rawQuery("PRAGMA application_id",null)){PortfolioMirrorModel.need(q.moveToFirst()&&q.getInt(0)==1347244595,"拒绝打开非本模块数据库，未改旧库");}}SQLiteDatabase db=guardedOpen(SQLiteDatabase.OPEN_READWRITE|SQLiteDatabase.CREATE_IF_NECESSARY);try{pragma(db,"PRAGMA busy_timeout=1500");if(!existed){pragma(db,"PRAGMA application_id=1347244595");try(Cursor marker=db.rawQuery("PRAGMA application_id",null)){PortfolioMirrorModel.need(marker.moveToFirst()&&marker.getInt(0)==1347244595,"新镜像库应用标记写入失败，未继续建表");}db.execSQL("CREATE TABLE mirror_records(id TEXT PRIMARY KEY,kind TEXT NOT NULL,account_id TEXT NOT NULL,series_id TEXT NOT NULL,saved_at TEXT NOT NULL,body TEXT NOT NULL)");db.execSQL("CREATE TABLE mirror_view(k TEXT PRIMARY KEY,body TEXT NOT NULL)");}try(Cursor q=db.rawQuery("SELECT name FROM sqlite_master WHERE type='table' AND name IN ('mirror_records','mirror_view')",null)){PortfolioMirrorModel.need(q.getCount()==2,"镜像库结构损坏，未重建");}return db;}catch(Exception e){db.close();throw e;}}
 private static String body(SQLiteDatabase db,String table,String id)throws Exception{String column=table.equals("mirror_view")?"k":"id";int length;try(Cursor q=db.rawQuery("SELECT length(body) FROM "+table+" WHERE "+column+"=?",new String[]{id})){if(!q.moveToFirst())return "";length=q.getInt(0);}PortfolioMirrorModel.need(length>=0&&length<=32*1024*1024,"镜像记录超过32MiB字符上限，未截断");StringBuilder out=new StringBuilder();for(int offset=1;offset<=length;offset+=24000)try(Cursor q=db.rawQuery("SELECT substr(body,?,24000) FROM "+table+" WHERE "+column+"=?",new String[]{Integer.toString(offset),id})){PortfolioMirrorModel.need(q.moveToFirst(),"镜像原文分段读取失败");out.append(q.getString(0));}PortfolioMirrorModel.need(out.toString().getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"镜像记录超过32MiB字节上限");return out.toString();}
 private static JSONArray catalog(SQLiteDatabase db)throws Exception{JSONArray rows=new JSONArray();try(Cursor q=db.rawQuery("SELECT id,kind,account_id,series_id,saved_at FROM mirror_records ORDER BY saved_at,id",null)){while(q.moveToNext()){PortfolioMirrorModel.need(rows.length()<10000,"镜像版本超过10000条，未截断");rows.put(PortfolioMirrorModel.object("id",q.getString(0),"kind",q.getString(1),"accountId",q.getString(2),"seriesId",q.getString(3),"savedAt",q.getString(4)));}}return rows;}
 JSONArray catalog()throws Exception{try(SQLiteDatabase db=open()){return catalog(db);}}
 String catalogFingerprint()throws Exception{return PortfolioMirrorModel.hash(catalog());}
 JSONObject get(String id)throws Exception{try(SQLiteDatabase db=open()){String raw=body(db,"mirror_records",id);PortfolioMirrorModel.need(!raw.isEmpty(),"镜像版本不存在");JSONObject r=PortfolioMirrorModel.validateRecord(PortfolioMirrorJson.parse(raw));PortfolioMirrorModel.need(r.getString("id").equals(id),"镜像主键与内容不一致");if(r.getString("kind").equals("comparison")){String original=body(db,"mirror_records",r.getString("mirrorId"));PortfolioMirrorModel.need(!original.isEmpty(),"对账引用版本不存在");JSONObject mirror=PortfolioMirrorModel.validateRecord(PortfolioMirrorJson.parse(original));PortfolioMirrorModel.need(mirror.getString("kind").equals("mirror")&&mirror.getString("accountId").equals(r.getString("accountId"))&&PortfolioMirrorModel.equal(mirror.getJSONObject("draft").get("mirror"),r.get("mirror")),"对账引用不一致");}return r;}}
 void append(JSONArray records,String expectedCatalog)throws Exception{PortfolioMirrorModel.need(records.length()>0&&records.length()<=10000,"没有可保存镜像版本");Set<String>ids=new HashSet<>();for(int i=0;i<records.length();i++){JSONObject r=PortfolioMirrorModel.validateRecord(records.getJSONObject(i));PortfolioMirrorModel.need(r.toString().getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"单版本超过32MiB");PortfolioMirrorModel.need(ids.add(r.getString("id")),"导入重复版本ID");}try(SQLiteDatabase db=open()){db.beginTransaction();try{PortfolioMirrorModel.need(PortfolioMirrorModel.hash(catalog(db)).equals(expectedCatalog),"预览后镜像历史已变化，请重读而非覆盖");for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);String id=r.getString("id"),old=body(db,"mirror_records",id);if(!old.isEmpty()){PortfolioMirrorModel.need(PortfolioMirrorModel.equal(PortfolioMirrorModel.validateRecord(PortfolioMirrorJson.parse(old)),r),"同ID版本内容冲突，未覆盖");continue;}if(r.getString("kind").equals("comparison")){String original=body(db,"mirror_records",r.getString("mirrorId"));PortfolioMirrorModel.need(!original.isEmpty(),"对账记录引用的镜像不存在；先导入镜像");JSONObject m=PortfolioMirrorModel.validateRecord(PortfolioMirrorJson.parse(original));PortfolioMirrorModel.need(m.getString("kind").equals("mirror")&&m.getString("accountId").equals(r.getString("accountId"))&&PortfolioMirrorModel.equal(m.getJSONObject("draft").get("mirror"),r.get("mirror")),"对账引用账户或镜像不一致");}ContentValues values=new ContentValues();values.put("id",id);values.put("kind",r.getString("kind"));values.put("account_id",r.getString("accountId"));values.put("series_id",r.getString("seriesId"));values.put("saved_at",r.getString("savedAt"));values.put("body",r.toString());db.insertOrThrow("mirror_records",null,values);}PortfolioMirrorModel.need(catalog(db).length()<=10000,"镜像库版本超限");db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 String exportText()throws Exception{JSONArray records=new JSONArray(),rows=catalog();for(int i=0;i<rows.length();i++)records.put(get(rows.getJSONObject(i).getString("id")));String text=PortfolioMirrorModel.object("schema","portfolio-mirror/v1","records",records).toString();PortfolioMirrorModel.need(text.getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"全量导出超过32MiB，请明确选择范围；未截断");return text;}
 JSONObject loadView()throws Exception{try(SQLiteDatabase db=open()){String raw=body(db,"mirror_view","view");if(raw.isEmpty())return new JSONObject();JSONObject o=PortfolioMirrorJson.parse(raw);PortfolioMirrorModel.need(o.getString("schema").equals("portfolio-mirror-view/v1"),"草稿损坏，未重建");return o;}}
 void saveView(JSONObject o,JSONObject expected)throws Exception{PortfolioMirrorModel.need(o.getString("schema").equals("portfolio-mirror-view/v1")&&o.toString().getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"草稿/预览结构无效或超过32MiB");try(SQLiteDatabase db=open()){db.beginTransaction();try{String raw=body(db,"mirror_view","view");JSONObject old=raw.isEmpty()?new JSONObject():PortfolioMirrorJson.parse(raw);PortfolioMirrorModel.need(PortfolioMirrorModel.equal(old,expected),"草稿已被其他页面修改，请显式重读");ContentValues v=new ContentValues();v.put("k","view");v.put("body",o.toString());db.insertWithOnConflict("mirror_view",null,v,SQLiteDatabase.CONFLICT_REPLACE);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
}
